<?php
include __DIR__.'/gmail-recipients.php';
$totalMail=(int)$db->query('SELECT (SELECT COUNT(*) FROM mail_deliveries)+(SELECT COUNT(*) FROM account_mail)')->fetchColumn();$mailPages=max(1,(int)ceil($totalMail/10));$mailPage=min(max(1,(int)filter_input(INPUT_GET,'mail_page',FILTER_VALIDATE_INT)),$mailPages);$mailOffset=($mailPage-1)*10;
panel_start('Alert and account email history','10 records per page. Sent means accepted by Gmail SMTP. Incident links open the supporting evidence.');
$deliveries=$db->query("SELECT * FROM (SELECT CONCAT('INC-MAIL-',d.id) mail_id,i.id incident_id,i.title purpose,COALESCE(NULLIF(CONCAT(s.first_name,' ',s.last_name),' '),NULLIF(e.user_identifier,''),'Anonymous') account_name,d.recipient,d.status,d.attempts,d.sent_at,d.last_error,d.created_at FROM mail_deliveries d LEFT JOIN incidents i ON i.id=d.incident_id LEFT JOIN security_events e ON e.id=i.event_id LEFT JOIN student_accounts s ON s.student_number=e.user_identifier UNION ALL SELECT CONCAT('ACCOUNT-MAIL-',m.id),NULL,REPLACE(m.kind,'_',' '),COALESCE(CONCAT(s.first_name,' ',s.last_name),m.student_number),m.recipient,m.status,m.attempts,m.sent_at,m.last_error,m.created_at FROM account_mail m LEFT JOIN student_accounts s ON s.student_number=m.student_number) messages ORDER BY created_at DESC,mail_id DESC LIMIT 10 OFFSET ".$mailOffset)->fetchAll(PDO::FETCH_ASSOC);
?>
<div class="table-scroll"><table><thead><tr><th>ACCOUNT</th><th>ALERT / PURPOSE</th><th>RECIPIENT</th><th>STATUS</th><th>ATTEMPTS</th><th>SENT AT</th><th>DELIVERY DETAILS</th></tr></thead><tbody>
<?php foreach($deliveries as $delivery):?><tr><td><?=h($delivery['account_name'])?></td><td><?php if($delivery['incident_id']):?><a class="row-action" href="?page=incidents&amp;incident=<?=(int)$delivery['incident_id']?>#investigation">INC-<?=(int)$delivery['incident_id']?> / <?=h($delivery['purpose'])?></a><?php else:?><?=h(ucfirst($delivery['purpose']))?><?php endif;?></td><td><?=h($delivery['recipient'])?></td><td><?=h(ucfirst($delivery['status']))?></td><td><?=(int)$delivery['attempts']?></td><td><?=h($delivery['sent_at']?:'Not sent yet')?></td><td><?=h($delivery['last_error']?:'?')?></td></tr><?php endforeach;if(!$deliveries):?><tr><td colspan="7">No alert emails have been queued yet.</td></tr><?php endif;?></tbody></table></div>
<?php ?>
<nav class="record-pager gmail-pager" aria-label="Email delivery history pages"><span><?= $totalMail?$mailOffset+1:0 ?>?<?=min($mailOffset+10,$totalMail)?> of <?=$totalMail?> records</span><div><?php if($mailPage>1):?><a class="button" href="?page=alerts&amp;mail_page=<?=$mailPage-1?>">Previous</a><?php else:?><span class="pager-disabled" aria-disabled="true">Previous</span><?php endif;?><span>Page <?=$mailPage?> of <?=$mailPages?></span><?php if($mailPage<$mailPages):?><a class="button" href="?page=alerts&amp;mail_page=<?=$mailPage+1?>">Next</a><?php else:?><span class="pager-disabled" aria-disabled="true">Next</span><?php endif;?></div></nav></article>
